#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define WIDTH 2400
#define HEIGHT 1800

int main(){
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", WIDTH, HEIGHT);

    for(int y = 0; y < HEIGHT; y++){
        for(int x = 0; x < WIDTH; x++){
            int r, g, b;

            if(y < 900){
                // Top gradient section
                float ty = (float)y / 28.33f;
                float tx = fabs((float)x - WIDTH/2.0f) / 1200.0f;
                float vignette = 1.0f - tx * 0.15f;

                r = (int)(159.0f + ty) * vignette;
                g = (int)(197.0f + ty * 0.63f) * vignette;
                b = 255;

                if(r > 255) r = 255;
                if(g > 255) g = 255;
            } else {
                // Bottom checkerboard section
                int bx = x / 33;
                int by = (y - 900) / 67;

                // Mix checkerboard with pseudo-random
                int h = ((bx * 73856093) ^ (by * 19349663)) % 256;

                if((h ^ ((x/50) * 17) ^ ((y/50) * 23)) % 3 == 0){
                    r = g = b = 67;
                } else if(x > 1080 && x < 1320 && y < 1200){
                    r = 51; g = 10; b = 10;
                } else {
                    r = g = b = 152;
                }
            }

            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0;
}

