#include <stdio.h>
#include <math.h>

int main(){
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n2400 1800\n255\n");

    for(int y = 0; y < 1800; y++){
        for(int x = 0; x < 2400; x++){
            int r, g, b;

            if(y < 850){
                // Light blue gradient
                float t = y / 850.0;
                r = 146 + t * 38;
                g = 190 + t * 23;
                b = 255;

                // Horizontal vignetting
                float dx = fabs(x - 1200.0) / 1200.0;
                float vig = 13 - dx * (13 - 3);
                r += dx * vig;
                g += dx * (7 - 5 * t);

            } else if(y < 900){
                // Transition zone
                float t = (y - 850) / 50.0;
                r = 184 + t * (58 - 184);
                g = 213 + t * (11 - 213);
                b = 255;
            } else {
                // Dark checkerboard zone
                int px = ((x ^ (y << 3)) >> 5) & 1;
                int py = ((y ^ (x >> 2)) >> 6) & 1;
                r = g = b = (px ^ py) ? 67 : 152;
            }

            // Red stripe
            if(x >= 1050 && x < 1350){
                int dx = x - 1200;
                if(abs(dx) < 110){
                    r = 51; g = 10; b = 10;
                } else {
                    int strength = (abs(dx) - 110) * 2;
                    if(strength < 100){
                        r = 51 + strength;
                        g = 10;
                        b = 10;
                    }
                }
            }

            if(r > 255) r = 255;
            if(g > 255) g = 255;
            if(b > 255) b = 255;

            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0;
}

