#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(){
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n2400 1800\n255\n");

    for(int y = 0; y < 1800; y++){
        for(int x = 0; x < 2400; x++){
            int r, g, b;

            if(y < 900){
                // Light blue gradient - base value at center
                float t = y / 900.0;
                r = (int)(146 + t * 41);
                g = (int)(190 + t * 23);
                b = 255;

                // Add edge enhancement based on distance from center x=1200
                float dx_norm = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                float edge_add_r = (13 - t * 10) * dx_norm;
                float edge_add_g = (7 - t * 5) * dx_norm;
                r += (int)edge_add_r;
                g += (int)edge_add_g;

            } else {
                // Checkerboard zone
                int bx = (x >> 5) % 3;
                int by = (y >> 6) % 3;
                int hash = ((x >> 7) * 73 + (y >> 7) * 97) & 1;

                if((bx + by + hash) & 1){
                    r = g = b = 67;
                } else {
                    r = g = b = 152;
                }

                // Red stripe overlay (only in bottom section)
                if(x > 1040 && x < 1360){
                    int dx = x - 1200;
                    int abs_dx = dx < 0 ? -dx : dx;

                    if(abs_dx <= 110){
                        r = 51; g = 10; b = 10;
                    } else if(abs_dx < 150){
                        int fade = (abs_dx - 110) * 3 / 2;
                        r = 51 + fade;
                        g = 10;
                        b = 10;
                    }
                }
            }

            if(r > 255) r = 255;
            if(g > 255) g = 255;
            if(b > 255) b = 255;

            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0;
}

