    for(int y = 0; y < 1800; y++){
        for(int x = 0; x < 2400; x++){
            int r, g, b;

            if(y < 900){
                // Light blue gradient - base value at center
                float t = y / 899.0f;
                r = 146 + (int)(t * 38.5f);
                g = 190 + (int)(t * 23.0f);
                b = 255;

                // Add edge enhancement - vignetting effect
                float dx = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                float t_sq = t * t;
                float vig_r = (13.0f - t_sq * 10.5f) * dx;
                float vig_g = (7.0f - t * 5.5f) * dx;
                r += (int)vig_r;
                g += (int)vig_g;

            } else {
                // Checkerboard - primarily based on XOR pattern
                int pattern = ((x ^ y) >> 6) & 1;
                r = g = b = pattern ? 67 : 152;

                // Red stripe overlay
                if(x >= 1050 && x <= 1310){
                    int dx = x - 1180;
                    if(dx * dx < 8100){  // approx 90 pixel radius
                        r = 51; g = 10; b = 10;
                    } else {
                        // Gradient transition
                        int strength = (abs(dx) - 90) * 2 / 3;
                        if(strength < 110){
                            r = 51 + strength;
                            g = 10 + (strength >> 2);
                            b = 10;
                        }
                    }
                }
