#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(){
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n2400 1800\n255\n");

    for(int y = 0; y < 1800; y++){
        for(int x = 0; x < 2400; x++){
            int r, g, b;

            if(y < 810){
                // Light blue gradient - base value at center
                float t = y / 810.0f;
                r = 146 + (int)(t * 38.0f);
                g = 190 + (int)(t * 23.0f);
                b = 255;

                // Add edge enhancement - vignetting effect
                float dx = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                float t_sq = t * t;
                float vig_r = (13.0f - t_sq * 10.0f) * dx;
                float vig_g = (7.0f - t * 5.0f) * dx;
                r += (int)vig_r;
                g += (int)vig_g;

            } else if(y < 856){
                // Transition zone with red stripe appearing
                float trans_t = (y - 809) / 47.0f;  // Map to 0-1 over the transition
                if(trans_t < 0) trans_t = 0;

                // Distance from center affects when red takes over
                float dist_norm = fabs(x - 1200) / 200.0f;
                float red_spread = trans_t - dist_norm * 0.3f;
                red_spread = red_spread < 0 ? 0 : (red_spread > 1.0f ? 1.0f : red_spread);

                if(red_spread > 0.5f){
                    // Red stripe region
                    r = 148 - (int)(trans_t * 97);
                    g = 29 - (int)(trans_t * 19);
                    b = 29 - (int)(trans_t * 19);
                } else {
                    // Still mostly gradient
                    float t = y / 850.0f;
                    r = 146 + (int)(t * 39.0f);
                    g = 190 + (int)(t * 24.0f);
                    b = 255;

                    float dx = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                    float t_sq = t * t;
                    r += (int)((13.0f - t_sq * 10.0f) * dx);
                    g += (int)((7.0f - t * 5.0f) * dx);
                }

            } else if(y < 900){
                // Pure red at center, checkerboard edges emerging
                r = 51; g = 10; b = 10;

            } else {
                // Checkerboard using LCG-based noise
                unsigned int seed = (y - 900) * 1103515245 + x * 12345;
                seed = (seed ^ (seed >> 16)) * 0x7feb352d;
                seed ^= seed >> 15;
                int pattern = (seed >> 16) & 1;
                r = g = b = pattern ? 152 : 67;

                // Red stripe overlay
                if(x >= 1050 && x <= 1310){
                    int dx = x - 1180;
                    if(dx * dx < 8100){
                        r = 51; g = 10; b = 10;
                    } else {
                        int strength = (abs(dx) - 90) * 2 / 3;
                        if(strength < 110){
                            r = 51 + strength;
                            g = 10 + (strength >> 2);
                            b = 10;
                        }
                    }
                }
            }

            if(r > 255) r = 255;
            if(g > 255) g = 255;
            if(b > 255) b = 255;

            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0;
}

