#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(){
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n2400 1800\n255\n");

    for(int y = 0; y < 1800; y++){
        for(int x = 0; x < 2400; x++){
            int r, g, b;

            if(y < 810){
                // Light blue gradient - base value at center
                float t = y / 810.0f;
                r = 146 + (int)(t * 38.0f);
                g = 190 + (int)(t * 23.0f);
                b = 255;

                // Add edge enhancement - vignetting effect
                float dx = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                float t_sq = t * t;
                float vig_r = (13.0f - t_sq * 10.0f) * dx;
                float vig_g = (7.0f - t * 5.0f) * dx;
                r += (int)vig_r;
                g += (int)vig_g;

            } else if(y < 900){
                // Transition zone 810-900: gradient with red stripe at center
                // Red stripe gradually increases from y=809 to y=856
                float base_t = y / 850.0f;
                r = 146 + (int)(base_t * 39.0f);
                g = 190 + (int)(base_t * 24.0f);
                b = 255;

                // Vignetting
                float dx = (x < 1200) ? (1200 - x) / 1200.0f : (x - 1200) / 1200.0f;
                float t_sq = base_t * base_t;
                r += (int)((13.0f - t_sq * 10.0f) * dx);
                g += (int)((7.0f - base_t * 5.0f) * dx);

                // Red stripe overlay at center, strongest after y=856
                if(y >= 809){
                    float red_t = (y - 809) / 47.0f;  // 0 at y=809, 1 at y=856
                    if(red_t > 1.0f) red_t = 1.0f;

                    // Distance from center affects red intensity
                    float center_dist = fabs(x - 1200) / 300.0f;
                    float red_intensity = red_t * (1.0f - center_dist * 0.5f);
                    if(red_intensity < 0) red_intensity = 0;

                    r = (int)(r * (1.0f - red_intensity) + 51 * red_intensity);
                    g = (int)(g * (1.0f - red_intensity) + 10 * red_intensity);
                    b = (int)(b * (1.0f - red_intensity));
                }

            } else {
                // Checkerboard pattern in bottom section
                int pattern = ((x ^ y) >> 6) & 1;
                r = g = b = pattern ? 67 : 152;

                // Red stripe overlay
                if(x >= 1050 && x <= 1310){
                    int dx = x - 1180;
                    if(dx * dx < 9000){
                        r = 51; g = 10; b = 10;
                    } else {
                        int strength = (abs(dx) - 95) * 2 / 3;
                        if(strength < 110){
                            r = 51 + strength;
                            g = 10 + (strength / 4);
                            b = 10;
                        }
                    }
                }
            }

            if(r > 255) r = 255;
            if(g > 255) g = 255;
            if(b > 255) b = 255;

            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0;
}

